            raise ValueError(\"empty key\")
        if key in result:
            raise ValueError(f\"duplicate key: {key"'!r}")
        position = end + 1
        while position < len(text) and text[position].isspace():
            position += 1
        if position < len(text) and text[position] == QUOTE:
            position += 1
            value = []
            while True:
                if position == len(text):
                    raise ValueError("unclosed quote")
                ch = text[position]
                position += 1
                if ch != QUOTE:
                    value.append(ch)
                elif position < len(text) and text[position] == QUOTE:
                    value.append(QUOTE)
                    position += 1
                else:
                    break
            while position < len(text) and text[position].isspace():
                position += 1
            if position < len(text) and text[position] != SEP:
                raise ValueError("unexpected text after quoted value")
            result[key] = "".join(value)
        else:
            end = position
            while end < len(text) and text[end] != SEP:
                end += 1
            value = text[position:end].strip()
            if QUOTE in value:
                raise ValueError("quote in unquoted value")
            result[key] = value
            position = end
        position += 1
    return result
'"'''
